{"arguments":{"content":""""Feature engineering + classical ML baselines for both lasso peptide instances."""
import numpy as np
import pandas as pd
from collections import Counter

AA = "ACDEFGHIKLMNPQRSTVWY"
AAIDX = {a: i for i, a in enumerate(AA)}


def aac(seq):
    c = np.zeros(20)
    for a in seq:
        i = AAIDX.get(a)
        if i is not None:
            c[i] += 1
    return c / max(1, len(seq))


def aac_cnt(seq):
    c = np.zeros(20)
    for a in seq:
        i = AAIDX.get(a)
        if i is not None:
            c[i] += 1
    return c


def dipeptide(seq):
    d = np.zeros(400)
    for i in range(len(seq) - 1):
        a, b = AAIDX.get(seq[i]), AAIDX.get(seq[i + 1])
        if a is not None and b is not None:
            d[a * 20 + b] += 1
    return d / max(1, len(seq) - 1)


# Physicochemical scales (Kyte-Doolittle hydropathy, charge, MW, pI-ish)
HYDRO = {'A': 1.8, 'R': -4.5, 'N': -3.5, 'D': -3.5, 'C': 2.5, 'Q': -3.5, 'E': -3.5,
         'G': -0.4, 'H': -3.2, 'I': 4.5, 'L': 3.8, 'K': -3.9, 'M': 1.9, 'F': 2.8,
         'P': -1.6, 'S': -0.8, 'T': -0.7, 'W': -0.9, 'Y': -1.3, 'V': 4.2}
CHARGE = {'K': 1, 'R': 1, 'H': 0.5, 'D': -1, 'E': -1}
MW = {'A': 89.1, 'R': 174.2, 'N': 132.1, 'D': 133.1, 'C': 121.2, 'Q': 146.2, 'E': 147.1,
      'G': 75.0, 'H': 155.2, 'I': 131.2, 'L': 131.2, 'K': 146.2, 'M': 149.2, 'F': 165.2,
      'P': 115.1, 'S': 105.1, 'T': 119.1, 'W': 204.2, 'Y': 181.2, 'V': 117.1}


def basic_physchem(seq):
    n = max(1, len(seq))
    hyd = [HYDRO.get(a, 0.0) for a in seq]
    chg = [CHARGE.get(a, 0.0) for a in seq]
    return np.array([
        len(seq),
        np.mean(hyd), np.std(hyd), np.sum(hyd) / n,
        np.sum(chg) / n, np.abs(np.sum(chg)) / n,
        sum(MW.get(a, 0) for a in seq) / n,
        seq.count('C') / n, seq.count('P') / n, seq.count('G') / n, seq.count('W') / n,
        seq.count('D') / n, seq.count('E') / n, seq.count('K') / n, seq.count('R') / n,
        seq.count('H') / n, seq.count('F') / n, seq.count('Y') / n,
    ], dtype=np.float64)


def pep_features(seq):
    """Position-aware features for fixed-length (28aa) peptide."""
    f = [list(aac(seq)), basic_physchem(seq)]
    onehot = np.zeros((len(seq), 20))
    for i, a in enumerate(seq):
        j = AAIDX.get(a)
        if j is not None:
            onehot[i, j] = 1
    f.append(onehot.reshape(-1))
    return np.concatenate(f)


def cyclase_features(seq, max_len=1024):
    f = [aac(seq), basic_physchem(seq)]
    # simple 3-block downsampled one-hot (N-term, mid, C-term) to keep size sane
    blocks = []
    for b in (0, 1, 2):
        sub = seq[b * len(seq) // 3:(b + 1) * len(seq) // 3]
        blocks.append(aac(sub))
    f.extend(blocks)
    f.append(dipeptide(seq) * 0)  # placeholder keeps dims stable
    return np.concatenate(f)


def core_features(seq):
    f = [aac(seq), basic_physchem(seq)]
    # terminal residues matter for lasso peptides (acceptor pos 1/2, plugs)
    terms = [seq[0], seq[1], seq[-1], seq[-2], seq[-3]]
    oh = np.zeros((5, 20))
    for i, a in enumerate(terms):
        j = AAIDX.get(a)
        if j is not None:
            oh[i, j] = 1
    f.append(oh.reshape(-1))
    return np.concatenate(f)
