{"arguments":{"content":""""Validate cyclase-pair models using ESM2 embeddings (+ handcrafted features)."""
import os, sys, time
import numpy as np
import pandas as pd
from sklearn.metrics import accuracy_score
import lightgbm as lgb

DATA = "/task/problem/data/cyclase_peptide_pair"
CACHE = "/workspace/cache"
TAG = sys.argv[1] if len(sys.argv) > 1 else "650m"


def emb(name):
    return np.load(os.path.join(CACHE, f"{name}_{TAG}.npy")).astype(np.float32)


tr = pd.read_csv(f"{DATA}/train.csv"); va = pd.read_csv(f"{DATA}/val.csv"); te = pd.read_csv(f"{DATA}/test_input.csv")

# build lookup index for unique sequences (order matches embed_all.py)
cyc_all, core_all = [], []
seen_c, seen_p = set(), set()
for df in (tr, va, te):
    for s in df["Cyclase sequence"]:
        if s not in seen_c:
            seen_c.add(s); cyc_all.append(s)
    for s in df["Core"]:
        if s not in seen_p:
            seen_p.add(s); core_all.append(s)
ci = {s: i for i, s in enumerate(cyc_all)}
pi = {s: i for i, s in enumerate(core_all)}

Ec, Ep = emb("cyc_enz"), emb("cyc_core")


def pair_feats(df):
    Ei = Ec[np.array([ci[s] for s in df["Cyclase sequence"]])]
    Pi = Ep[np.array([pi[s] for s in df["Core"]])]
    return np.hstack([Ei, Pi, np.abs(Ei - Pi), Ei * Pi])


Xtr, Xva, Xte = pair_feats(tr), pair_feats(va), pair_feats(te)
ytr, yva = tr.label.values, va.label.values
print(Xtr.shape)
t0 = time.time()
m = lgb.LGBMClassifier(n_estimators=1500, learning_rate=0.03, num_leaves=63,
                       subsample=0.8, subsample_freq=1, colsample_bytree=0.6,
                       n_jobs=32, verbose=-1)
m.fit(Xtr, ytr)
pv = m.predict(Xva)
print("val acc", accuracy_score(yva, pv), f"{time.time()-t0:.0f}s")
