{"arguments":{"content":""""Training utilities for the pair MLP: dataset, training loop with pos_weight."""
import numpy as np
import torch
import torch.nn as nn
from torch.utils.data import Dataset, DataLoader


class PairDS(Dataset):
    def __init__(self, X, y=None):
        self.X = torch.from_numpy(X.astype(np.float32))
        self.y = torch.from_numpy(y.astype(np.float32)) if y is not None else None

    def __len__(self):
        return len(self.X)

    def __getitem__(self, i):
        if self.y is None:
            return self.X[i]
        return self.X[i], self.y[i]


def standardize_fit(X, mask_cols=None):
    mu = X.mean(0, keepdims=True)
    sd = X.std(0, keepdims=True) + 1e-6
    return mu, sd


def train_mlp(Xtr, ytr, Xva, yva, in_dim, hidden=1536, dropout=0.3, epochs=30,
              bs=4096, lr=1e-3, pos_weight=1.0, wd=1e-5, device="cuda",
              seed=0, n_ens=3, patience=4, verbose=True, model_cls=None):
    """Train an ensemble of MLPs; returns (model_list, val_scores_each_fold)."""
    from features import PairMLP
    model_cls = model_cls or PairMLP
    mu = Xtr.mean(0, keepdims=True)
    sd = Xtr.std(0, keepdims=True) + 1e-6
    Xtr_n = (Xtr - mu) / sd
    Xva_n = (Xva - mu) / sd if Xva is not None else None

    torch.manual_seed(seed)
    tr_ds = PairDS(Xtr_n, ytr)
    g = torch.Generator().manual_seed(seed)
    tr_dl = DataLoader(tr_ds, batch_size=bs, shuffle=True, generator=g,
                       num_workers=2, drop_last=True, pin_memory=True)

    models = []
    val_scores = []
    for k in range(n_ens):
        torch.manual_seed(seed * 1000 + k)
        net = model_cls(in_dim, hidden, dropout).to(device)
        opt = torch.optim.AdamW(net.parameters(), lr=lr, weight_decay=wd)
        sched = torch.optim.lr_scheduler.CosineAnnealingLR(opt, T_max=epochs)
        crit = nn.BCEWithLogitsLoss(pos_weight=torch.tensor(pos_weight, device=device))
        best_ap, best_state, bad = -1, None, 0
        for ep in range(epochs):
            net.train()
            for xb, yb in tr_dl:
                xb, yb = xb.to(device, non_blocking=True), yb.to(device, non_blocking=True)
                opt.zero_grad(set_to_none=True)
                loss = crit(net(xb), yb)
                loss.backward()
                opt.step()
            sched.step()
            if Xva is not None:
                from common import aupr
                sc = predict(net, Xva_n, device=device)
                ap = aupr(yva, sc)
                if ap > best_ap + 1e-5:
                    best_ap, bad = ap, 0
                    best_state = {kk: vv.detach().clone() for kk, vv in net.state_dict().items()}
                else:
                    bad += 1
                if verbose:
                    print(f"    ens{k} ep{ep} valAUPR={ap:.4f} best={best_ap:.4f}", flush=True)
                if bad >= patience:
                    break
        if best_state is not None:
            net.load_state_dict(best_state)
        models.append(net)
        val_scores.append(best_ap)
    return models, (mu, sd), val_scores


@torch.no_grad()
def predict(net, X, device="cuda", bs=8192):
    net.eval()
    outs = []
    X = torch.from_numpy(X.astype(np.float32))
    for i in range(0, len(X), bs):
        outs.append(torch.sigmoid(net(X[i:i + bs].to(device))).cpu().numpy())
    return np.concatenate(outs)


@torch.no_grad()
def predict_ens(models, X, stats, device="cuda", bs=16384):
    mu, sd = stats
    Xn = (X - mu) / sd
    preds = [predict(m, Xn, device, bs) for m in models]
    return np.mean(preds, axis=0)
