{"arguments":{"content":""""Population-prior post-processing.

The number of localizations per cluster is roughly constant within an
instance (molecules x blinking).  Two systematic DBSCAN failure modes can
therefore be repaired:

* over-populated groups  -> two clusters that touched: split with k-means
  into round(pop / expected) parts;
* under-populated groups -> background fluctuations: demote to 0.
"""
import numpy as np
from scipy.cluster.vq import kmeans2


def split_overpopulated(xy, lab, n_loc, hi=1.6, max_splits=4, lo=0.75):
    lab = lab.copy()
    next_id = int(lab.max()) + 1
    for c in np.unique(lab[lab > 0]):
        idx = np.where(lab == c)[0]
        pop = len(idx)
        k = int(round(pop / n_loc))
        if pop <= hi * n_loc or k < 2:
            continue
        k = min(k, max_splits)
        p = xy[idx]
        # kmeans++ style init from the k most distant points
        try:
            cent, ass = kmeans2(p, k, minit="++", seed=0, iter=30)
        except Exception:
            continue
        # only accept the split if all parts are reasonably populated
        sizes = np.bincount(ass, minlength=k)
        if (sizes < lo * n_loc * 0.5).any():
            continue
        for s in range(1, k):
            lab[idx[ass == s]] = next_id
            next_id += 1
    return relabel(lab)


def drop_small(lab, min_pop):
    lab = lab.copy()
    vals, cnts = np.unique(lab[l > 0] if False else lab[lab > 0], return_counts=True)
    for v, c in zip(vals, cnts):
        if c < min_pop:
            lab[lab == v] = 0
    return relabel(lab)


def relabel(lab):
    out = np.zeros(len(lab), dtype=np.int64)
    for new, v in enumerate(np.unique(lab[lab > 0]), start=1):
        out[lab == v] = new
    return out
