{"arguments":{"content":""""Probe candidate ARI_r definitions against the official scores.

Official (tuned DBSCAN run): s5 0.661, s6 0.656, s8b 0.868, s8n 0.805.
"""
import glob, os, sys
import numpy as np, pandas as pd
from sklearn.cluster import DBSCAN
from sklearn.metrics import adjusted_rand_score

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))

DATA = "/task/problem/data"
FILES = {
    "scenario_5_blinking": "highden_DetectionList_*.csv",
    "scenario_6_blinking": "elliptical_w_noise_DetectionList_*.csv",
    "scenario_8_blinking": "diffden_DetectionList*.csv",
    "scenario_8_no_blinking": "diffden_MoleculeList_*.csv",
}
TUNED = {
    "scenario_5_blinking": dict(eps=24.0, min_samples=15),
    "scenario_6_blinking": dict(eps=40.0, min_samples=40),
    "scenario_8_blinking": dict(eps=35.0, min_samples=10),
    "scenario_8_no_blinking": dict(eps=50.0, min_samples=5),
}
OFFICIAL = {"scenario_5_blinking": 0.661, "scenario_6_blinking": 0.656,
            "scenario_8_blinking": 0.868, "scenario_8_no_blinking": 0.805}


def dbscan_labels(xy, cfg):
    lab = DBSCAN(**cfg).fit(xy).labels_.astype(int)
    out = np.zeros(len(lab), dtype=int)
    for new, v in enumerate(np.unique(lab[lab > 0]), start=1):
        out[lab == v] = new
    return out


def ari_singleton_bg(y_true, y_pred):
    """Background points become their own singleton clusters in both."""
    t = y_true.copy()
    p = y_pred.copy()
    nt = t.max() + 1
    for i in np.where(t == 0)[0]:
        t[i] = nt
        nt += 1
    np_ = p.max() + 1
    for i in np.where(p == 0)[0]:
        p[i] = np_
        np_ += 1
    return adjusted_rand_score(t, p)


def ari_union(y_true, y_pred):
    m = (y_true > 0) | (y_pred > 0)
    return adjusted_rand_score(y_true[m], y_pred[m])


def ari_bg_ignored_pairs(y_true, y_pred):
    """ARI over pairs where at least one member is a gt-cluster point."""
    idx = np.where(y_true > 0)[0]
    return adjusted_rand_score(y_true[idx], y_pred[idx])


def fmeasure_hm(y_true, y_pred, bg_w=0.25):
    scores, weights = [], []
    for c in np.unique(y_true):
        mask = y_true == c
        n = float(mask.sum())
        vals, cnts = np.unique(y_pred[mask], return_counts=True)
        pl = vals[np.argmax(cnts)]
        recall = cnts.max() / n
        precision = float((y_pred[mask] == pl).sum()) / max(float((y_pred == pl).sum()), 1.0)
        f = 2 * precision * recall / (precision + recall) if (precision + recall) else 0.0
        scores.append(f)
        weights.append(n if c != 0 else n * bg_w)
    s = np.clip(np.array(scores), 1e-9, 1.0)
    w = np.array(weights, float)
    return float(w.sum() / (w / s).sum())


def fmeasure_hm_nobg(y_true, y_pred):
    return fmeasure_hm(y_true[y_true > 0], y_pred[y_true > 0])


def fmeasure_hm_predpersp(y_true, y_pred, bg_w=0.25):
    """F-measure per *predicted* cluster, harmonic mean."""
    scores, weights = [], []
    for c in np.unique(y_pred):
        mask = y_pred == c
        n = float(mask.sum())
        vals, cnts = np.unique(y_true[mask], return_counts=True)
        pl = vals[np.argmax(cnts)]
        recall = cnts.max() / n
        precision = float((y_true[mask] == pl).sum()) / max(float((y_true == pl).sum()), 1.0)
        f = 2 * precision * recall / (precision + recall) if (precision + recall) else 0.0
        scores.append(f)
        weights.append(n if pl != 0 else n * bg_w)
    s = np.clip(np.array(scores), 1e-9, 1.0)
    w = np.array(weights, float)
    return float(w.sum() / (w / s).sum())


CANDS = {
    "singleton_bg": ari_singleton_bg,
    "union": ari_union,
    "gt_only": ari_bg_ignored_pairs,
    "fm_hm": fmeasure_hm,
    "fm_hm_nobg": fmeasure_hm_nobg,
    "fm_hm_pred": fmeasure_hm_predpersp,
    "plain_ari": adjusted_rand_score,
}

if __name__ == "__main__":
    for inst, pat in FILES.items():
        vals = {k: [] for k in CANDS}
        for f in sorted(glob.glob(os.path.join(DATA, inst, "train", pat))):
            d = pd.read_csv(f)
            xy = d[["x", "y"]].to_numpy(float)
            gt = d["index"].to_numpy(int)
            pred = dbscan_labels(xy, TUNED[inst])
            for k, fn in CANDS.items():
                vals[k].append(fn(gt, pred))
        line = f"{inst} (official {OFFICIAL[inst]:.3f}): "
        for k in CANDS:
            line += f"{k}={np.mean(vals[k]):.3f} "
        print(line)
","file_path":"/workspace/probe_arir.py"},"name":"Write"}

