{"arguments":{"content":""""Combine prediction files into /workspace/output/ct_nodules/predictions.npy.

Rank-averages the selected prediction files (robust to per-model calibration differences);
this is invariant to monotone transforms and hence preserves ROC-AUC ordering.
Usage: python combine.py tag1 tag2 ... | file1.npy file2.npy | auto
"""
import os, sys, glob
import numpy as np
from scipy.stats import rankdata

OUT = "/workspace/output/ct_nodules/predictions.npy"
PDIR = "/workspace/preds"


def collect(args):
    files = []
    for a in args:
        if a == "auto":
            files += sorted(glob.glob(os.path.join(PDIR, "*_test.npy")))
        elif a.endswith(".npy"):
            files.append(a if os.path.isabs(a) else os.path.join(PDIR, a))
        else:
            files.append(os.path.join(PDIR, f"{a}_test.npy"))
    seen, out = set(), []
    for f in files:
        if f not in seen:
            seen.add(f); out.append(f)
    return out


def main():
    files = collect(sys.argv[1:])
    if not files:
        raise SystemExit("no prediction files given")
    ps = []
    for f in files:
        p = np.load(f).astype(np.float64).ravel()
        print(f"  {f}  n={p.shape[0]} mean={p.mean():.3f}")
        ps.append(p)
    r = np.mean([rankdata(p) / len(p) for p in ps], 0)
    os.makedirs(os.path.dirname(OUT), exist_ok=True)
    np.save(OUT, r.astype(np.float32))
    print("saved", OUT, r.shape, float(r.mean()))


if __name__ == "__main__":
    main()
