{"arguments":{"content":""""Stable MLP trainer: warmup+cosine LR, grad clip, AMP off, log-MSE + cosine combo.
Used for both CV and full-data prediction."""
import numpy as np, torch, torch.nn as nn, sys, os

dev = 'cuda'


class Net(nn.Module):
    def __init__(s, ni, no, h=1024, dr=0.2, depth=3):
        super().__init__()
        layers = []
        for i in range(depth):
            layers += [nn.Linear(ni if i == 0 else h, h), nn.GELU(), nn.Dropout(dr)]
        layers += [nn.Linear(h, no)]
        s.n = nn.Sequential(*layers)

    def forward(s, x): return s.n(x)


def loss_fn(pred, tl, w_cos=1.0, w_mse=10.0):
    p = torch.expm1(torch.clamp(pred, max=8.))
    y = torch.expm1(tl)
    l = w_mse * ((pred - tl) ** 2).mean()
    if w_cos > 0:
        l = l + w_cos * (1 - nn.functional.cosine_similarity(p, y, dim=1)).mean()
    return l


def train(A, TY, B=None, h=1024, dr=0.2, depth=3, epochs=100, lr=1e-3, wd=1e-5,
          bs=256, seed=0, warmup=5, verbose=False, w_cos=1.0, w_mse=10.0):
    torch.manual_seed(seed)
    net = Net(A.shape[1], TY.shape[1], h, dr, depth).to(dev)
    opt = torch.optim.AdamW(net.parameters(), lr=lr, weight_decay=wd)
    n = A.shape[0]; steps = (n + bs - 1) // bs
    # warmup + cosine
    def lr_at(ep):
        if ep < warmup:
            return (ep + 1) / warmup
        t = (ep - warmup) / max(1, epochs - warmup)
        return 0.5 * (1 + np.cos(np.pi * t))
    sched = torch.optim.lr_scheduler.LambdaLR(opt, lr_at)
    for ep in range(epochs):
        net.train(); perm = torch.randperm(n, device=dev)
        for s in range(steps):
            sl = perm[s*bs:(s+1)*bs]
            opt.zero_grad()
            l = loss_fn(net(A[sl]), TY[sl], w_cos, w_mse)
            l.backward()
            torch.nn.utils.clip_grad_norm_(net.parameters(), 5.0)
            opt.step()
        sched.step()
    net.eval()
    return net


def predict(net, B):
    with torch.no_grad():
        return torch.expm1(torch.clamp(net(B), max=8.)).cpu().numpy().astype(np.float64)
