{"arguments":{"content":""""Ensemble member trainer used by the final pipeline.
Each member is an MLP: [log-CPM HVG z-scores] -> [log-CLR protein profile]."""
import numpy as np, torch, torch.nn as nn


class MLP(nn.Module):
    """Plain MLP with GELU + dropout between layers."""

    def __init__(self, ni, no, h=1024, dr=0.2, depth=3):
        super().__init__()
        layers = []
        for i in range(depth):
            layers += [nn.Linear(ni if i == 0 else h, h), nn.GELU(), nn.Dropout(dr)]
        layers += [nn.Linear(h, no)]
        self.n = nn.Sequential(*layers)

    def forward(self, x):
        return self.n(x)


def loss_fn(pred, target_log, w_mse=10.0, w_cos=1.0):
    """log-space MSE + cosine on linear-scale profiles."""
    p = torch.expm1(torch.clamp(pred, max=8.0))
    y = torch.expm1(target_log)
    loss = w_mse * ((pred - target_log) ** 2).mean()
    if w_cos > 0:
        loss = loss + w_cos * (1 - nn.functional.cosine_similarity(p, y, dim=1)).mean()
    return loss


def train_member(A, TY, h=1024, dr=0.2, depth=3, epochs=100, lr=1e-3, wd=1e-5,
                 bs=256, seed=0, warmup=5, clip=5.0, device='cuda', w_mse=10.0, w_cos=1.0):
    torch.manual_seed(seed)
    net = MLP(A.shape[1], TY.shape[1], h, dr, depth).to(device)
    opt = torch.optim.AdamW(net.parameters(), lr=lr, weight_decay=wd)
    n = A.shape[0]
    steps = (n + bs - 1) // bs

    def lr_at(ep):
        if ep < warmup:
            return (ep + 1) / warmup
        t = (ep - warmup) / max(1, epochs - warmup)
        return 0.5 * (1.0 + np.cos(np.pi * t))

    sched = torch.optim.lr_scheduler.LambdaLR(opt, lr_at)
    for ep in range(epochs):
        net.train()
        perm = torch.randperm(n, device=device)
        for s in range(steps):
            sl = perm[s * bs:(s + 1) * bs]
            opt.zero_grad()
            loss = loss_fn(net(A[sl]), TY[sl], w_mse, w_cos)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(net.parameters(), clip)
            opt.step()
        sched.step()
    net.eval()
    return net


@torch.no_grad()
def predict_clr(net, B, device='cuda'):
    """Return linear-scale CLR profile (rows sum to 1)."""
    p = torch.expm1(torch.clamp(net(B), max=8.0)).cpu().numpy().astype(np.float64)
    s = p.sum(1, keepdims=True)
    return p / np.maximum(s, 1e-12)
