{"arguments":{"content":""""Trivial baseline: write an ideal-helix PDB for every target (fallback only)."""
import os, math

DATA_DIR = os.environ.get("DATA_DIR", "/task/problem/data")
OUTPUT_DIR = os.environ.get("OUTPUT_DIR", "/workspace/output")
INSTANCES = ["benchmark_i", "benchmark_ii"]

# Ideal alpha-helix backbone geometry (per-residue rise/turn)
RISE = 1.50
TWIST = math.radians(100.0)
RADIUS = 2.28

def helix_pdb(seq, chain="A"):
    lines = []
    for i, aa in enumerate(seq):
        x = RADIUS * math.cos(i * TWIST)
        y = RADIUS * math.sin(i * TWIST)
        z = i * RISE
        if i == len(seq) - 1:
            at = "OXT"
        else:
            at = "O  "
        lines.append(
            "ATOM  %5d  CA  %3s %s%4d    %8.3f%8.3f%8.3f  1.00  0.00           C"
            % (i + 1, "GLY", chain, i + 1, x, y, z)
        )
    lines.append("TER")
    lines.append("END")
    return "\n".join(lines) + "\n"

def read_seq(path):
    seq = []
    with open(path) as f:
        for line in f:
            line = line.strip()
            if line.startswith(">") or not line:
                continue
            seq.append(line)
    return "".join(seq)

def main():
    for inst in INSTANCES:
        os.makedirs(os.path.join(OUTPUT_DIR, inst), exist_ok=True)
        ids_file = os.path.join(DATA_DIR, inst, "ids")
        ids = [l.strip() for l in open(ids_file) if l.strip()]
        for pid in ids:
            sf = os.path.join(DATA_DIR, inst, pid, "seq.fasta")
            if not os.path.exists(sf):
                continue
            seq = read_seq(sf)
            with open(os.path.join(OUTPUT_DIR, inst, pid + ".pdb"), "w") as f:
                f.write(helix_pdb(seq))

if __name__ == "__main__":
    main()
