{"arguments":{"content":""""RCSB search API client: remote sequence search + structure download."""
import json
import time
import urllib.parse
import urllib.request

SEARCH_URL = "https://search.rcsb.org/rcsbsearch/v2/query"
DATA_URL = "https://data.rcsb.org/rest/v1/core"
DOWNLOAD_URL = "https://files.rcsb.org/download"


def _get(url, timeout=60, retries=3):
    for i in range(retries):
        try:
            req = urllib.request.Request(url, headers={"User-Agent": "structure-prediction/1.0"})
            with urllib.request.urlopen(req, timeout=timeout) as r:
                return r.read()
        except Exception:
            if i == retries - 1:
                raise
            time.sleep(1.5 * (i + 1))
    return None


def seq_search(seq, identity_cutoff=0.3, evalue_cutoff=1.0, rows=25, timeout=60):
    """Return list of (entity_id 'PDB_CHAIN', score)."""
    q = {
        "query": {
            "type": "terminal",
            "service": "sequence",
            "parameters": {
                "evalue_cutoff": evalue_cutoff,
                "identity_cutoff": identity_cutoff,
                "sequence_type": "protein",
                "value": seq,
            },
        },
        "return_type": "polymer_entity",
        "request_options": {
            "paginate": {"start": 0, "rows": rows},
            "results_content_type": ["experimental"],
            "scoring_strategy": "sequence",
        },
    }
    url = SEARCH_URL + "?json=" + urllib.parse.quote(json.dumps(q))
    data = _get(url, timeout=timeout)
    if data is None:
        return []
    res = json.loads(data)
    return [(r["identifier"], r["score"]) for r in res.get("result_set", [])]


def entity_info(entity_id):
    """entity_id like '4HHB_1'; returns dict of polymer entity instance."""
    return json.loads(_get(f"{DATA_URL}/polymer_entity/{entity_id}", timeout=60))


def entry_info(pdb_id):
    return json.loads(_get(f"{DATA_URL}/entry/{pdb_id}", timeout=60))


def download_pdb(pdb_id, path, fmt="pdb"):
    data = _get(f"{DOWNLOAD_URL}/{pdb_id}.{fmt}", timeout=120)
    with open(path, "wb") as f:
        f.write(data)
    return path
