{"arguments":{"content":""""Spatial transcriptomics utilities: graph construction, smoothing, Moran's I."""
import numpy as np
import scipy.sparse as sp


def sym(W):
    return ((W + W.T) > 0).astype(np.float64).tocsr()


def knn_graph(X, k=8, mode="connectivity"):
    from sklearn.neighbors import kneighbors_graph
    A = kneighbors_graph(X, k, mode=mode, include_self=False)
    return sym(A)


def morans_i(W, x):
    W = W.tocsr()
    n = x.shape[0]
    z = x - x.mean()
    num = float(np.asarray(W.dot(z)).flatten().dot(z))
    return (n / max(W.sum(), 1e-9)) * num / (float(z.dot(z)) + 1e-12)


def smooth(W, X, n_iter=1, alpha=1.0):
    """Graph smoothing of features X (rows = cells)."""
    D = np.asarray(W.sum(1)).flatten()
    D[D == 0] = 1.0
    Y = X.copy()
    for _ in range(n_iter):
        Y = (1 - alpha) * Y + alpha * (W.dot(Y) / D[:, None])
    return Y
