{"arguments":{"content":""""Local reproduction of CBDir / k-CBDir for offline velocity optimization."""
import numpy as np
import anndata as ad
import scipy.sparse as sp


def load(inst):
    a = ad.read_h5ad(f"/task/problem/data/{inst}/data.h5ad")
    return a


def neigh_pairs(a, use="spatial"):
    W = a.obsp["spatial_graph"].astype(float)
    W = ((W + W.T) > 0).astype(float)
    return sp.triu(W, k=1).nonzero()


def cbdir(V, M, pairs, cl, src, dst):
    """mean cosine(v_i, M_j - M_i) over pairs (i,j) with cl_i=src, cl_j=dst (either orientation)."""
    cs = []
    for i, j in zip(*pairs):
        if cl[i] == src and cl[j] == dst:
            d = M[j] - M[i]; v = V[i]
        elif cl[j] == src and cl[i] == dst:
            d = M[i] - M[j]; v = V[j]
        else:
            continue
        nv = np.linalg.norm(v) * np.linalg.norm(d)
        if nv > 0:
            cs.append(float(v.dot(d) / nv))
    return (np.mean(cs) if cs else 0.0), len(cs)


def cbdir_multi(V, M, pairs, cl, transitions):
    vals, ns = [], []
    for s, d in transitions:
        v, n = cbdir(V, M, pairs, cl, s, d)
        if n:
            vals.append(v); ns.append(n)
    return float(np.average(vals, weights=ns)) if vals else 0.0, ns


if __name__ == "__main__":
    import sys
    inst = sys.argv[1] if len(sys.argv) > 1 else "thymus"
    a = load(inst)
    cl = a.obs["clusters"].astype(str).values
    print("clusters:", np.unique(cl))
    M = np.asarray(a.layers["Ms"])
    V = np.load(f"/workspace/output/{inst}/velocity.npy")
    pairs = neigh_pairs(a)
    print("pairs:", len(pairs[0]))
    # all ordered cluster pairs
    us = np.unique(cl)
    for s in us:
        for d in us:
            if s == d:
                continue
            v, n = cbdir(V, M, pairs, cl, s, d)
            if n:
                print(f"  {s:12s} -> {d:12s}  cbdir={v:+.4f}  n={n}")
","file_path":"/workspace/cbdir.py"},"name":"Write"}

