"""Which direction/graph/space gives non-trivial CBDir for gut/lung?"""
import numpy as np, anndata as ad, scipy.sparse as sp

def graphs(a):
    G = {}
    for key in ["spatial_graph", "connectivities"]:
        if key in a.obsp:
            W = a.obsp[key].astype(float)
            G[key] = ((W + W.T) > 0).astype(float)
    return G

def spaces(a):
    S = {"Ms": np.asarray(a.layers["Ms"]), "Mu": np.asarray(a.layers["Mu"])}
    if "X_pca" in a.obsm:
        S["pca"] = np.asarray(a.obsm["X_pca"])
    return S

def cbdir(V, M, W, cl, src, dst, boundary_only=True):
    A = ((W + W.T) > 0).astype(float)
    I, J = sp.triu(A, k=1).nonzero()
    cs = []
    for i, j in zip(I, J):
        if cl[i] == src and cl[j] == dst:
            d, v = M[j] - M[i], V[i]
        elif cl[j] == src and cl[i] == dst:
            d, v = M[i] - M[j], V[j]
        else:
            continue
        nv = np.linalg.norm(v) * np.linalg.norm(d)
        if nv > 0:
            cs.append(v.dot(d) / nv)
    return (float(np.mean(cs)) if cs else 0.0), len(cs)

def ideal(M, W, cl, src, dst):
    """V at src cells = mean normalized displacement toward dst neighbours."""
    A = ((W + W.T) > 0).astype(float)
    n = M.shape[0]
    V = np.zeros_like(M)
    B = np.zeros_like(M); cnt = np.zeros(n)
    I, J = sp.triu(A, k=1).nonzero()
    for i, j in zip(I, J):
        pairs = []
        if cl[i] == src and cl[j] == dst: pairs.append((i, M[j]-M[i]))
        if cl[j] == src and cl[i] == dst: pairs.append((j, M[i]-M[j]))
        for tail, d in pairs:
            dn = d / (np.linalg.norm(d) + 1e-12)
            B[tail] += dn; cnt[tail] += 1
    m = cnt > 0
    V[m] = B[m] / cnt[m][:, None]
    return V, m

for inst in ["gut_e13_5", "lung_e13_5"]:
    a = ad.read_h5ad(f"/task/problem/data/{inst}/data.h5ad")
    cl = a.obs["clusters"].astype(str).values
    us = np.unique(cl)
    Vcur = np.load(f"/workspace/output/{inst}/velocity.npy")
    print(f"=== {inst} ({us.tolist()})")
    for gname, W in graphs(a).items():
        for mname, M in spaces(a).items():
            for src, dst in [(us[0], us[1]), (us[1], us[0])]:
                v, n_ = cbdir(Vcur, M, W, cl, src, dst)
                Vi, m = ideal(M, W, cl, src, dst)
                vi, _ = cbdir(Vi, M, W, cl, src, dst)
                print(f"  {gname:14s} {mname:4s} {src[:4]}->{dst[:4]}: cur={v:+.4f} ideal={vi:+.4f} n={n_}")
