"""Calibrate local CBDir variants against evaluator numbers (brain 0.3187, thymus 0.1802)."""
import numpy as np, anndata as ad, scipy.sparse as sp

def variants(a, V):
    cl = a.obs["clusters"].astype(str).values
    us = np.unique(cl)
    out = {}
    G = {"sp": ((a.obsp["spatial_graph"]+a.obsp["spatial_graph"].T)>0).astype(float),
         "co": ((a.obsp["connectivities"].astype(float)+a.obsp["connectivities"].astype(float).T)>0).astype(float)}
    S = {"Ms": np.asarray(a.layers["Ms"]),
         "Mu": np.asarray(a.layers["Mu"])}
    sp_l = a.layers["spliced"]; sp_l = sp_l.toarray() if sp.issparse(sp_l) else np.asarray(sp_l)
    S["spliced"] = sp_l
    S["log1p_sp"] = np.log1p(sp_l)
    if "X_pca" in a.obsm:
        S["pca"] = np.asarray(a.obsm["X_pca"])
    res = {}
    for gn, W in G.items():
        I, J = sp.triu(W, k=1).nonzero()
        for mn, M in S.items():
            if M.shape[1] != V.shape[1] and mn != "pca":
