            if mn == "pca":
                # project velocity onto PCA? skip: mismatch dims -> use pca coords as space, V on genes invalid
                continue
            for s in us:
                for d in us:
                    if s == d: continue
                    cs = []
                    for i, j in zip(I, J):
                        if cl[i] == s and cl[j] == d:
                            dd, v = M[j]-M[i], V[i]
                        elif cl[j] == s and cl[i] == d:
                            dd, v = M[i]-M[j], V[j]
                        else: continue
                        nv = np.linalg.norm(v)*np.linalg.norm(dd)
                        if nv > 0: cs.append(v.dot(dd)/nv)
                    if cs:
                        res[f"{gn}|{mn}|{s[:6]}->{d[:6]}"] = float(np.mean(cs))
    return res

for inst, target in [("brain_cortex", 0.3187), ("thymus", 0.1802)]:
