import numpy as np, anndata as ad, scipy.sparse as sp
for inst in ["gut_e13_5","lung_e13_5","brain_cortex","thymus"]:
    a = ad.read_h5ad(f"/task/problem/data/{inst}/data.h5ad")
    cl = a.obs["clusters"].astype(str).values
    V = np.load(f"/workspace/output/{inst}/velocity.npy")
    W = ((a.obsp["spatial_graph"]+a.obsp["spatial_graph"].T)>0).astype(float)
    I,J = sp.triu(W,k=1).nonzero()
    spaces = {}
    spaces["Ms"]=np.asarray(a.layers["Ms"])
    X = a.X.toarray() if sp.issparse(a.X) else np.asarray(a.X)
    spaces["X"]=X
    spaces["logX"]=np.log1p(X)
    S = a.layers["spliced"]; S = S.toarray() if sp.issparse(S) else np.asarray(S)
    spaces["logS"]=np.log1p(S)
    print("==",inst)
    for nm,M in spaces.items():
        cs=[]
        for i,j in zip(I,J):
            if cl[i]!=cl[j]:
                cs.append(V[i].dot(M[j]-M[i]))
        # unnormalized dot only meaningful relative; use cosine
        cs=[]
        for i,j in zip(I,J):
            if cl[i]!=cl[j]:
                d=M[j]-M[i]; nv=np.linalg.norm(V[i])*np.linalg.norm(d)
                if nv>0: cs.append(V[i].dot(d)/nv)
        print(f"   cosine(V_ms, d{nm:5s}) = {np.mean(cs):+.4f}")
