            d=M[j]-M[i]; dn=d/(np.linalg.norm(d)+1e-12)
            B[i]+=dn; cnt[i]+=1; B[j]-=dn; cnt[j]+=1
    m=cnt>0; V=np.zeros_like(M,dtype=float); V[m]=B[m]/cnt[m][:,None]
    return V

for inst in ["gut_e13_5","lung_e13_5","brain_cortex","thymus"]:
    a = ad.read_h5ad(f"/task/problem/data/{inst}/data.h5ad")
    cl = a.obs["clusters"].astype(str).values
    S = a.layers["spliced"]; S = S.toarray() if sp.issparse(S) else np.asarray(S)
    S = S.astype(float)
    W0 = ((a.obsp["spatial_graph"]+a.obsp["spatial_graph"].T)>0).astype(float)
    Ms = np.asarray(a.layers["Ms"]).astype(float)
    I,J = sp.triu(W0,k=1).nonzero()
    cross = cl[I]!=cl[J]
    res={}
    for nm, M in [("logS",np.log1p(S)),("sqrtS",np.sqrt(S)),("Ms",Ms)]:
        V = bfield(M,W0,cl)
        cs=[]
        for i,j in zip(I,J):
            if cl[i]!=cl[j]:
                d=Ms[j]-Ms[i]; nv=np.linalg.norm(V[i])*np.linalg.norm(d)
                if nv>0: cs.append(V[i].dot(d)/nv)
        # also self-consistency: cos(V_logS, d_logS) on cross pairs
        cs2=[]
        for i,j in zip(I,J):
            if cl[i]!=cl[j]:
                d=M[j]-M[i]; nv=np.linalg.norm(V[i])*np.linalg.norm(d)
                if nv>0: cs2.append(V[i].dot(d)/nv)
        res[nm]=(np.mean(cs),np.mean(cs2))
    print(inst, {k:(round(v[0],4),round(v[1],4)) for k,v in res.items()})
EOF","description":"Compare logS/sqrtS/Ms fields across all real instances"},"name":"Bash"}

