from localcb import load
import numpy as np, scipy.sparse as sp
from spatial_utils import knn_graph

# Which pair set reproduces the evaluator's CBDir?  Score the shipped field
# under several candidate edge sets.
target={'brain_cortex':0.7639,'gut_e13_5':0.7793,'lung_e13_5':0.7409,'thymus':0.8718}
def cbdir(V,M,pairs,cl):
    I,J=pairs; cs=[]
    for i,j in zip(I,J):
        if cl[i]==cl[j]: continue
        d=M[j]-M[i]
        for v,dd in ((V[i],d),(V[j],-d)):
            nv=np.linalg.norm(v)*np.linalg.norm(dd)
            if nv>0: cs.append(float(v.dot(dd)/nv))
    return float(np.mean(cs)) if cs else 0.0

for inst in target:
    a,S,W=load(inst)
    cl=a.obs['clusters'].astype(str).values
    X=np.asarray(a.obsm['X_spatial'],float)
    V=np.load(f'/workspace/output/{inst}/velocity.npy')
    rows=[]
    W0=((W+W.T)>0).astype(float)
    rows.append(('spatial_graph',cbdir(V,S,sp.triu(W0,k=1).nonzero(),cl)))
    for k in [6,8,10,15,30]:
        Wk=knn_graph(X,k=k); Wk=((Wk+Wk.T)>0).astype(float)
        rows.append((f'knn{k}',cbdir(V,S,sp.triu(Wk,k=1).nonzero(),cl)))
    print(inst,'target',target[inst], {n:round(v,4) for n,v in rows})
