# Directional (one-orientation) CBDir: score each boundary edge only from the
# cell in cluster A toward cluster B, using a fixed cluster ordering, and see
# which ordering matches the evaluator numbers.
def cbdir_dir(V,M,pairs,cl,src,dst):
    I,J=pairs; cs=[]
    for i,j in zip(I,J):
        if cl[i]==src and cl[j]==dst:
            d=M[j]-M[i]; v=V[i]
        elif cl[j]==src and cl[i]==dst:
            d=M[i]-M[j]; v=V[j]
        else: continue
        nv=np.linalg.norm(v)*np.linalg.norm(d)
        if nv>0: cs.append(float(v.dot(dd)/nv) if False else float(v.dot(d)/nv))
    return float(np.mean(cs)) if cs else 0.0, len(cs)

target={'brain_cortex':0.7639,'gut_e13_5':0.7793,'lung_e13_5':0.7409,'thymus':0.8718}
