    a,S,W=load(inst)
    cl=a.obs['clusters'].astype(str).values
    V=np.load(f'/workspace/output/{inst}/velocity.npy')
    pairs=sp.triu(((W+W.T)>0).astype(float),k=1).nonzero()
    us=sorted(np.unique(cl))
    print(inst,'clusters',us,'target',target[inst])
    for s in us:
