def cbdir_pairs(V,M,pairs,cl):
    I,J=pairs; cs=[]
    for i,j in zip(I,J):
        if cl[i]==cl[j]: continue
        d=M[j]-M[i]
        for v,dd in ((V[i],d),(V[j],-d)):
            nv=np.linalg.norm(v)*np.linalg.norm(dd)
            if nv>0: cs.append(float(v.dot(dd)/nv))
    return float(np.mean(cs)) if cs else 0.0

def cbdir_edges(V,M,pairs,cl):
    # one score per edge (average of the two orientations)
    I,J=pairs; cs=[]
    for i,j in zip(I,J):
        if cl[i]==cl[j]: continue
        d=M[j]-M[i]
        c1=c2=None
        nv=np.linalg.norm(V[i])*np.linalg.norm(d)
        if nv>0: c1=float(V[i].dot(d)/nv)
        nv=np.linalg.norm(V[j])*np.linalg.norm(d)
        if nv>0: c2=float(V[j].dot(-d)/nv)
        parts=[c for c in (c1,c2) if c is not None]
        if parts: cs.append(float(np.mean(parts)))
    return float(np.mean(cs)) if cs else 0.0

target={'brain_cortex':0.7639,'gut_e13_5':0.7793,'lung_e13_5':0.7409,'thymus':0.8718}
