    pairs=sp.triu(((W+W.T)>0).astype(float),k=1).nonzero()
    print(inst,'target',target[inst],'per-orientation',round(cbdir_pairs(V,S,pairs,cl),4),'per-edge',round(cbdir_edges(V,S,pairs,cl),4))
