        d=M[j]-M[i]
        for v,dd in ((V[i],d),(V[j],-d)):
            nv=np.linalg.norm(v)*np.linalg.norm(dd)
            if nv>0: cs.append(float(v.dot(dd)/nv))
    return float(np.mean(cs)) if cs else 0.0

def cbdir_cellmean(V,M,pairs,cl):
    # per-cell mean over that cell's boundary edges, then unweighted mean over cells
    I,J=pairs
    from collections import defaultdict
    acc=defaultdict(list)
    for i,j in zip(I,J):
        if cl[i]==cl[j]: continue
        d=M[j]-M[i]
        nv=np.linalg.norm(V[i])*np.linalg.norm(d)
        if nv>0: acc[i].append(float(V[i].dot(d)/nv))
        nv=np.linalg.norm(V[j])*np.linalg.norm(d)
        if nv>0: acc[j].append(float(V[j].dot(-d)/nv))
    return float(np.mean([np.mean(v) for v in acc.values()]))

