import numpy as np
import glob, os, json

base = '/task/problem/data/simulated_generalization/'

def parse_pdb(path):
    lines = open(path, errors='ignore').read().splitlines()
    xyz, elems = [], []
    for L in lines:
        if L.startswith(('ATOM', 'HETATM')):
            try:
                x = float(L[30:38]); y = float(L[38:46]); z = float(L[46:54])
            except ValueError:
                continue
            el = L[76:78].strip()
            if not el:
                el = L[12:16].strip()[0]
            xyz.append((x, y, z)); elems.append(el)
    return np.array(xyz), elems


def analyze(path):
    xyz, elems = parse_pdb(path)
    if len(xyz) == 0:
        return None
    c = xyz.mean(0)
    d = np.linalg.norm(xyz - c, axis=1)
    heavy = [i for i, e in enumerate(elems) if e != 'H']
    if heavy:
        dh = np.linalg.norm(xyz[heavy] - xyz[heavy].mean(0), axis=1)
    else:
        dh = d
    return dict(n=len(xyz), n_heavy=len(heave:=heavy), rmax=d.max(), rg=np.sqrt((d**2).mean()),
                rg_h=np.sqrt((dh**2).mean()), rmax_h=dh.max())

out = {}
# training rounds: pdbs dir per round
for r in range(1, 12):
    pdir = base + f'tomo_simulation_round_{r}/pdbs'
    for f in sorted(os.listdir(pdir)):
        if not f.endswith('.pdb'):
            continue
        a = analyze(os.path.join(pdir, f))
        if a:
            out[f[:-4]] = a
# test proteins
for f in sorted(os.listdir(base + 'test_tomogram/pdbs')):
    if f.endswith('.pdb'):
        a = analyze(base + 'test_tomogram/pdbs/' + f)
        if a:
            out['TEST_' + f[:-4]] = a

for k in sorted(out):
    a = out[k]
    print(f"{k:12s} n={a['n']:6d} rmax={a['rmax']:7.1f} rg={a['rg']:7.1f} rg_h={a['rg_h']:7.1f} rmax_h={a['rmax_h']:7.1f} vox_rmax={a['rmax_h']/10:5.1f}")
