{"arguments":{"content":""""PDB -> density template at tomogram voxel size (10.205 A/voxel).

Particles appear as POSITIVE density in raw reconstructions.
"""
import numpy as np


def parse_pdb(path):
    xyz, w = [], []
    for L in open(path, errors="ignore"):
        if L.startswith(("ATOM", "HETATM")):
            try:
                x = float(L[30:38]); y = float(L[38:46]); z = float(L[46:54])
            except ValueError:
                continue
            el = L[76:78].strip()
            if not el:
                el = L[12:16].strip()[0]
            w.append(1.0 if el != "H" else 0.0)
            xyz.append((x, y, z))
    return np.array(xyz), np.array(w)


def pdb_to_density(path, vox=10.205, box=37, sigma=1.2, center=True):
    """Gaussian-blurred heavy-atom density in a box^3 array."""
    xyz, w = parse_pdb(path)
    if center:
        xyz = xyz - xyz[w > 0].mean(0) if (w > 0).any() else xyz - xyz.mean(0)
    c = box // 2
    f = xyz / vox + c
    dens = np.zeros((box, box, box), np.float32)
    grid = np.arange(box)
    gz, gy, gx = np.meshgrid(grid, grid, grid, indexing="ij")
    s2 = 2 * sigma * sigma
    for (x, y, z), wi in zip(f, w):
        if wi <= 0:
            continue
        d2 = (gx - x) ** 2 + (gy - y) ** 2 + (gz - z) ** 2
        m = d2 < 9 * s2
        dens[m] += wi * np.exp(-d2[m] / s2)
    dens -= dens.mean()
    return dens


if __name__ == "__main__":
    import sys
    d = pdb_to_density(sys.argv[1])
    print(d.shape, d.min(), d.max(), np.linalg.norm(d))
","file_path":"/workspace/pdb_density.py"},"name":"Write"}

