def run():
    r = subprocess.run(['curl','-s','-X','POST','http://host.docker.internal:8341/evaluate','-d',TOKEN],capture_output=True,text=True)
    return json.loads(r.stdout)['raw_scores']['simulated_validation']
B='/workspace/output_backup/simulated_validation'
files=sorted(glob.glob(f'{B}/round_*/*_coords.txt'))
data={f:np.loadtxt(f) for f in files}
GEN='/workspace/output_backup/simulated_generalization'
gfiles={os.path.basename(p):np.loadtxt(p) for p in sorted(glob.glob(f'{GEN}/*.txt'))}

def write_all(T):
    for f,c in data.items():
        d=f.replace('/output_backup/','/output/')
        os.makedirs(os.path.dirname(d),exist_ok=True)
        np.savetxt(d,T(c),fmt='%.3f')
    os.makedirs('/workspace/output/simulated_generalization',exist_ok=True)
    for b,c in gfiles.items():
        np.savetxt(f'/workspace/output/simulated_generalization/{b}',c,fmt='%.2f')

def rx(c): return np.stack([512-c[:,0],c[:,1],c[:,2]],1)
def ry(c): return np.stack([c[:,0],512-c[:,1],c[:,2]],1)
def rz(c): return np.stack([c[:,0],c[:,1],200-c[:,2]],1)
def sxy(c): return c[:,[1,0,2]]
def sxz(c): return c[:,[2,1,0]]
def syz(c): return c[:,[0,2,1]]
def sxy_r(c): return np.stack([512-c[:,1],c[:,0],c[:,2]],1)
def sxy_r2(c): return np.stack([c[:,1],512-c[:,0],c[:,2]],1)
def sxy_r3(c): return np.stack([512-c[:,1],512-c[:,0],c[:,2]],1)
def old_frame(c):
    # inverse of new = 0.98*[-old_y, old_x, old_z] + [256,256,100]
    x,y,z=c[:,0],c[:,1],c[:,2]
    return np.stack([(y-256)/0.98, -(x-256)/0.98, (z-100)/0.98],1)
def new_frame(c):
    x,y,z=c[:,0],c[:,1],c[:,2]
    return np.stack([256-0.98*y, 256+0.98*x, 100+0.98*z],1)

tests=[('identity',lambda c:c),('swap_xy',sxy),('swap_xz',sxz),('swap_yz',syz),
       ('rev_x',rx),('rev_y',ry),('rev_z',rz),
       ('sxy_rx',sxy_r),('sxy_ry',sxy_r2),('sxy_rxy',sxy_r3),
       ('old_frame',old_frame),('new_frame',new_frame)]
for name,T in tests:
    write_all(T)
    r=run()
    print(name,r,flush=True)
print('done')
